  "title": "enable-info-logging-transport",
  "request": "Hey, can you turn on INFO level logging for the client transport module so I can see its debug output? Just set the basic config after the import.",
  "edits": [
    {
      "path": "src/mcp/client/_transport.py",
      "search": "import logging",
      "replace": "import logging\nlogging.basicConfig(level=logging.INFO)"
    }
  ],
  "test_path": "tests/test_transport_logging.py",
  "test": "import importlib\nimport logging\n\ndef test_transport_logger_info_level():\n    # Reload the module to ensure the basicConfig line runs\n    mod = importlib.import_module(\"mcp.client._transport\")\n    importlib.reload(mod)\n    logger = logging.getLogger(\"mcp.client._transport\")\n    # The logger should inherit INFO level from the root after basicConfig\n    assert logger.getEffectiveLevel() == logging.INFO\n"
}
